import { useEffect, useState } from 'react';
import { Container, Text, Title } from '@mantine/core';
import { useForm } from '@mantine/form';
import { notifications } from '@mantine/notifications';
import { fetchAccountSettings } from './api';
import { BillingSection } from './BillingSection/BillingSection';
import { DangerZone } from './DangerZone/DangerZone';
import { emptyBilling, emptyNotifications, emptyOrganization, emptyProfile, MEMBERS } from './data';
import { formatList } from './format-list';
import { NotificationsSection } from './NotificationsSection/NotificationsSection';
import { OrganizationSection } from './OrganizationSection/OrganizationSection';
import { ProfileSection } from './ProfileSection/ProfileSection';
import { saveSections, type SettingsSectionEntry } from './save-sections';
import { SettingsSection } from './SettingsSection/SettingsSection';
import type {
  BillingValues,
  NotificationsValues,
  OrganizationValues,
  ProfileValues,
} from './types';
import { UnsavedChangesBar } from './UnsavedChangesBar/UnsavedChangesBar';
import { billingRules, notificationsRules, organizationRules, profileRules } from './validation';
import classes from './AccountSettings.module.css';

export function AccountSettings() {
  const [organizationName, setOrganizationName] = useState('');
  const [ownerId, setOwnerId] = useState<string | null>(null);
  const [loaded, setLoaded] = useState(false);
  const [saving, setSaving] = useState(false);

  const profileForm = useForm<ProfileValues>({
    name: 'profile-settings',
    initialValues: emptyProfile,
    validate: profileRules,
  });

  const organizationForm = useForm<OrganizationValues>({
    name: 'organization-settings',
    initialValues: emptyOrganization,
    validate: organizationRules,
  });

  const billingForm = useForm<BillingValues>({
    name: 'billing-settings',
    initialValues: emptyBilling,
    validate: billingRules,
    // Inputs of the copied address are rendered from the whole `address` object set at once
    cascadeUpdates: true,
  });

  const notificationsForm = useForm<NotificationsValues>({
    name: 'notification-settings',
    initialValues: emptyNotifications,
    validate: notificationsRules,
  });

  const sections: SettingsSectionEntry[] = [
    { id: 'profile', label: 'Profile', form: profileForm, dirty: profileForm.useDirty() },
    {
      id: 'organization',
      label: 'Organization',
      form: organizationForm,
      dirty: organizationForm.useDirty(),
    },
    { id: 'billing', label: 'Billing', form: billingForm, dirty: billingForm.useDirty() },
    {
      id: 'notifications',
      label: 'Notifications',
      form: notificationsForm,
      dirty: notificationsForm.useDirty(),
    },
  ];
  const dirtySections = sections.filter((section) => section.dirty);
  const hasUnsavedChanges = dirtySections.length > 0;

  useEffect(() => {
    let cancelled = false;
    void fetchAccountSettings().then((data) => {
      if (cancelled) {
        return;
      }
      profileForm.initialize(data.profile);
      organizationForm.initialize(data.organization);
      billingForm.initialize(data.billing);
      notificationsForm.initialize(data.notifications);
      setOrganizationName(data.organization.name);
      setOwnerId(data.ownerId);
      setLoaded(true);
    });
    return () => {
      cancelled = true;
    };
  }, []);

  useEffect(() => {
    if (!hasUnsavedChanges) {
      return undefined;
    }
    // The browser shows its own "Leave site?" dialog when preventDefault is called
    const handleBeforeUnload = (event: BeforeUnloadEvent) => event.preventDefault();
    window.addEventListener('beforeunload', handleBeforeUnload);
    return () => window.removeEventListener('beforeunload', handleBeforeUnload);
  }, [hasUnsavedChanges]);

  const handleCancel = () => dirtySections.forEach((section) => section.form.reset());

  const handleSave = async () => {
    setSaving(true);
    const result = await saveSections(dirtySections);
    setSaving(false);

    if (result.saved.some((section) => section.id === 'organization')) {
      setOrganizationName(organizationForm.getInitialValues().name);
    }

    if (result.failed.length === 0 && result.invalid.length === 0) {
      notifications.show({
        title: 'Changes saved',
        message: `${formatList(result.saved.map((section) => section.label))} updated`,
      });
      return;
    }

    const failedLabels = formatList([...result.invalid, ...result.failed].map((s) => s.label));
    notifications.show({
      color: 'red',
      title: `Could not save ${failedLabels}`,
      message: 'Check the highlighted fields and try again',
    });
  };

  return (
    <Container size="md" className={classes.root}>
      <div className={classes.header}>
        <Title order={2} c="var(--mantine-color-bright)">
          Account settings
        </Title>
        <Text size="sm">Manage your profile, organization and notification preferences.</Text>
      </div>

      <div className={classes.sections}>
        <SettingsSection
          title="Profile"
          description="How you appear to other members of your organization."
          loading={!loaded}
        >
          <ProfileSection form={profileForm} />
        </SettingsSection>

        <SettingsSection
          title="Organization"
          description="Company details shown on your workspace and documents."
          loading={!loaded}
        >
          <OrganizationSection form={organizationForm} />
        </SettingsSection>

        <SettingsSection
          title="Billing"
          description="Where invoices are sent and the address printed on them."
          loading={!loaded}
        >
          <BillingSection form={billingForm} organizationForm={organizationForm} />
        </SettingsSection>

        <SettingsSection
          title="Notifications"
          description="Choose which events reach you and through which channels."
          loading={!loaded}
        >
          <NotificationsSection form={notificationsForm} />
        </SettingsSection>

        <SettingsSection
          title="Danger zone"
          description="Actions that change who controls the organization or remove it for good."
          loading={!loaded}
        >
          <DangerZone
            organizationName={organizationName}
            members={MEMBERS.filter((member) => member.value !== ownerId)}
            onOwnershipTransferred={setOwnerId}
          />
        </SettingsSection>
      </div>

      <UnsavedChangesBar
        dirtySections={dirtySections.map((section) => section.label)}
        saving={saving}
        onCancel={handleCancel}
        onSave={handleSave}
      />
    </Container>
  );
}

.root {
  padding-top: var(--mantine-spacing-xl);
  /* Room for the unsaved changes bar so it never covers the last section */
  padding-bottom: 120px;
}

.header {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin-bottom: var(--mantine-spacing-xl);
}

.sections {
  display: flex;
  flex-direction: column;
  gap: calc(var(--mantine-spacing-xl) * 2);
}

import { render, screen, userEvent, waitFor, within } from '@test-utils';
import { afterEach, describe, expect, it, vi } from 'vite-plus/test';
import { Notifications, notifications } from '@mantine/notifications';
import { AccountSettings } from './AccountSettings';

const { delay } = vi.hoisted(() => ({
  delay: vi.fn<(ms: number) => Promise<void>>(() => Promise.resolve()),
}));
vi.mock('./delay', () => ({ delay }));

type User = ReturnType<typeof userEvent.setup>;

async function renderSettings() {
  const user = userEvent.setup();
  render(
    <>
      <Notifications />
      <AccountSettings />
    </>
  );
  await screen.findByRole('textbox', { name: 'Full name' });
  return { user };
}

const section = (name: string) => screen.getByRole('region', { name });
const saveButton = () => screen.queryByRole('button', { name: 'Save' });
const cancelButton = () => screen.getByRole('button', { name: 'Cancel' });

async function replaceText(user: User, field: HTMLElement, text: string) {
  await user.clear(field);
  if (text) {
    await user.type(field, text);
  }
}

async function pickOption(user: User, field: HTMLElement, option: string) {
  await user.click(field);
  await user.click(screen.getByRole('option', { name: option }));
}

afterEach(() => {
  notifications.clean();
  delay.mockClear();
});

describe('loading', () => {
  it('shows a loading state in every section until the settings arrive', async () => {
    render(<AccountSettings />);
    expect(screen.getAllByRole('status', { name: /^Loading .* settings$/ })).toHaveLength(5);
    expect(await screen.findByRole('textbox', { name: 'Full name' })).toBeInTheDocument();
    expect(screen.queryByRole('status', { name: /^Loading/ })).not.toBeInTheDocument();
  });

  it('fills the sections with the saved settings', async () => {
    await renderSettings();
    expect(screen.getByRole('textbox', { name: 'Full name' })).toHaveValue('Jane Cooper');
    expect(screen.getByRole('textbox', { name: 'Organization name' })).toHaveValue('Acme');
    expect(screen.getByRole('textbox', { name: 'Billing email' })).toHaveValue('billing@acme.com');
    expect(screen.getByRole('combobox', { name: 'Timezone' })).toHaveValue('Berlin');
  });
});

describe('unsaved changes bar', () => {
  it('is hidden while nothing has changed', async () => {
    await renderSettings();
    expect(saveButton()).not.toBeInTheDocument();
  });

  it('names the section that has changes', async () => {
    const { user } = await renderSettings();
    await user.type(screen.getByRole('textbox', { name: 'Job title' }), ' and Finance');
    expect(screen.getAllByText('Unsaved changes in Profile')[0]).toBeVisible();
  });

  it('names every section that has changes', async () => {
    const { user } = await renderSettings();
    await user.type(screen.getByRole('textbox', { name: 'Job title' }), ' and Finance');
    await user.click(screen.getByRole('checkbox', { name: 'Product updates by Email' }));
    expect(screen.getAllByText('Unsaved changes in Profile and Notifications')[0]).toBeVisible();
  });

  it('hides when a change is undone by hand', async () => {
    const { user } = await renderSettings();
    const legalName = screen.getByRole('textbox', { name: 'Legal name' });
    await user.type(legalName, 'X');
    expect(saveButton()).toBeInTheDocument();
    await user.type(legalName, '{Backspace}');
    expect(saveButton()).not.toBeInTheDocument();
  });

  it('reverts every changed section to its saved values on Cancel', async () => {
    const { user } = await renderSettings();
    await replaceText(user, screen.getByRole('textbox', { name: 'Full name' }), 'Ada Lovelace');
    await replaceText(user, screen.getByRole('textbox', { name: 'Tax ID' }), 'DE000');
    await user.click(cancelButton());

    expect(screen.getByRole('textbox', { name: 'Full name' })).toHaveValue('Jane Cooper');
    expect(screen.getByRole('textbox', { name: 'Tax ID' })).toHaveValue('DE123456789');
    expect(saveButton()).not.toBeInTheDocument();
  });

  it('shows a notification naming the saved sections', async () => {
    const { user } = await renderSettings();
    await replaceText(user, screen.getByRole('textbox', { name: 'Display name' }), 'JC');
    await replaceText(user, screen.getByRole('textbox', { name: 'Legal name' }), 'Acme AG');
    await user.click(saveButton()!);

    expect(await screen.findByText('Changes saved')).toBeInTheDocument();
    expect(screen.getByText('Profile and Organization updated')).toBeInTheDocument();
  });

  it('hides after saving', async () => {
    const { user } = await renderSettings();
    await replaceText(user, screen.getByRole('textbox', { name: 'Display name' }), 'JC');
    await user.click(saveButton()!);
    await waitFor(() => expect(saveButton()).not.toBeInTheDocument());
  });

  it('makes the saved values the baseline for Cancel', async () => {
    const { user } = await renderSettings();
    const displayName = screen.getByRole('textbox', { name: 'Display name' });
    await replaceText(user, displayName, 'JC');
    await user.click(saveButton()!);
    await screen.findByText('Changes saved');

    await user.type(displayName, '!');
    await user.click(cancelButton());
    expect(displayName).toHaveValue('JC');
  });

  it('shows Save as loading while the sections are being saved', async () => {
    const { user } = await renderSettings();
    let finishSave = () => {};
    delay.mockImplementationOnce(
      () =>
        new Promise((resolve) => {
          finishSave = resolve;
        })
    );
    await replaceText(user, screen.getByRole('textbox', { name: 'Display name' }), 'JC');
    await user.click(saveButton()!);

    expect(saveButton()).toHaveAttribute('data-loading');
    finishSave();
    expect(await screen.findByText('Changes saved')).toBeInTheDocument();
  });

  it('keeps a section with validation errors unsaved and focuses its first invalid field', async () => {
    const { user } = await renderSettings();
    await user.clear(screen.getByRole('textbox', { name: 'Full name' }));
    await user.click(saveButton()!);

    expect(screen.getByText('Enter your full name')).toBeInTheDocument();
    expect(screen.getByRole('textbox', { name: 'Full name' })).toHaveFocus();
    expect(screen.getAllByText('Unsaved changes in Profile')[0]).toBeVisible();
  });

  it('saves the valid sections when another section has errors', async () => {
    const { user } = await renderSettings();
    await user.clear(screen.getByRole('textbox', { name: 'Full name' }));
    await replaceText(user, screen.getByRole('textbox', { name: 'Legal name' }), 'Acme AG');
    await user.click(saveButton()!);

    await waitFor(() => expect(screen.getAllByText('Unsaved changes in Profile')[0]).toBeVisible());
    expect(await screen.findByText('Could not save Profile')).toBeInTheDocument();
  });
});

describe('profile', () => {
  it('rejects an invalid email', async () => {
    const { user } = await renderSettings();
    await replaceText(user, screen.getByRole('textbox', { name: 'Email' }), 'jane@');
    await user.click(saveButton()!);
    expect(screen.getByText('Enter a valid email address')).toBeInTheDocument();
  });

  it('shows the server error on the email field when the email is taken', async () => {
    const { user } = await renderSettings();
    const email = screen.getByRole('textbox', { name: 'Email' });
    await replaceText(user, email, 'taken@example.com');
    await user.click(saveButton()!);

    expect(
      await screen.findByText('This email is already used by another account')
    ).toBeInTheDocument();
    expect(email).toHaveAttribute('aria-invalid', 'true');
  });

  it('keeps the changes unsaved when the server rejects the email', async () => {
    const { user } = await renderSettings();
    await replaceText(user, screen.getByRole('textbox', { name: 'Email' }), 'taken@example.com');
    await user.click(saveButton()!);

    expect(await screen.findByText('Could not save Profile')).toBeInTheDocument();
    expect(screen.getAllByText('Unsaved changes in Profile')[0]).toBeVisible();
  });

  it('counts the bio characters', async () => {
    const { user } = await renderSettings();
    const bio = screen.getByRole('textbox', { name: 'Bio' });
    await replaceText(user, bio, 'Hello');
    expect(screen.getByText('5/200')).toBeInTheDocument();
  });

  it('stops the bio at 200 characters', async () => {
    const { user } = await renderSettings();
    const bio = screen.getByRole('textbox', { name: 'Bio' });
    await user.clear(bio);
    await user.click(bio);
    await user.paste('a'.repeat(210));
    expect(screen.getByText('200/200')).toBeInTheDocument();
  });
});

describe('organization', () => {
  it('rejects an invalid website', async () => {
    const { user } = await renderSettings();
    await replaceText(user, screen.getByRole('textbox', { name: 'Website' }), 'acme');
    await user.click(saveButton()!);
    expect(screen.getByText('Enter a valid URL, like https://acme.com')).toBeInTheDocument();
  });

  it('saves without a website', async () => {
    const { user } = await renderSettings();
    await user.clear(screen.getByRole('textbox', { name: 'Website' }));
    await user.click(saveButton()!);
    expect(await screen.findByText('Changes saved')).toBeInTheDocument();
  });

  it('requires the city of the address', async () => {
