      'Acme Labs'
    );
    await user.click(
      within(section('Danger zone')).getByRole('button', { name: 'Delete organization' })
    );
    expect(
      within(screen.getByRole('dialog')).getByRole('textbox', { name: 'Type Acme to confirm' })
    ).toBeInTheDocument();
  });
});

import { Fieldset, Select, SimpleGrid, Stack, TextInput } from '@mantine/core';
import type { FormPath, UseFormReturnType } from '@mantine/form';
import { COUNTRIES } from '../data';
import type { Address } from '../types';

interface AddressFieldsProps<Values> {
  form: UseFormReturnType<Values>;
  path: FormPath<Values, Address>;
  legend: string;
  disabled?: boolean;
}

export function AddressFields<Values>({
  form,
  path,
  legend,
  disabled,
}: AddressFieldsProps<Values>) {
  return (
    <Fieldset legend={legend} disabled={disabled}>
      <Stack gap="md">
        <TextInput
          label="Street"
          placeholder="Street and number"
          withAsterisk
          autoComplete="street-address"
          {...form.getInputProps(`${path}.street`)}
        />
        <SimpleGrid cols={{ base: 1, sm: 2 }}>
          <TextInput
            label="City"
            placeholder="City"
            withAsterisk
            autoComplete="address-level2"
            {...form.getInputProps(`${path}.city`)}
          />
          <TextInput
            label="Postal code"
            placeholder="Postal code"
            withAsterisk
            autoComplete="postal-code"
            {...form.getInputProps(`${path}.postalCode`)}
          />
        </SimpleGrid>
        <SimpleGrid cols={{ base: 1, sm: 2 }}>
          <Select
            label="Country"
            placeholder="Pick a country"
            data={COUNTRIES}
            withAsterisk
            allowDeselect={false}
            {...form.getInputProps(`${path}.country`)}
          />
          <TextInput
            label="State or region"
            placeholder="State or region"
            autoComplete="address-level1"
            {...form.getInputProps(`${path}.region`)}
          />
        </SimpleGrid>
      </Stack>
    </Fieldset>
  );
}

import { useCallback, useRef } from 'react';
import { Checkbox, Stack, Textarea, TextInput } from '@mantine/core';
import { AddressFields } from '../AddressFields/AddressFields';
import type { Address, BillingFormType, OrganizationFormType } from '../types';

interface BillingSectionProps {
  form: BillingFormType;
  organizationForm: OrganizationFormType;
}

export function BillingSection({ form, organizationForm }: BillingSectionProps) {
  const sameAsOrganization = form.useWatchValue('sameAsOrganization');
  // Billing address the copy replaced, restored when the checkbox is turned off
  const replacedAddress = useRef<Address | null>(null);

  const handleSameAsChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const checked = event.currentTarget.checked;
    if (checked) {
      replacedAddress.current = form.getValues().address;
      form.setFieldValue('address', { ...organizationForm.getValues().address });
    } else if (replacedAddress.current) {
      form.setFieldValue('address', replacedAddress.current);
      replacedAddress.current = null;
    }
    form.setFieldValue('sameAsOrganization', checked);
  };

  const syncWithOrganization = useCallback(
    ({ value }: { value: Address }) => {
      if (form.getValues().sameAsOrganization) {
        form.setFieldValue('address', { ...value });
      }
    },
    [form]
  );
  organizationForm.watch('address', syncWithOrganization);

  return (
    <Stack gap="md">
      <TextInput
        label="Billing email"
        placeholder="billing@example.com"
        withAsterisk
        inputMode="email"
        autoComplete="email"
        {...form.getInputProps('email')}
      />

      <Stack gap="xs">
        <Checkbox
          label="Same as organization address"
          {...form.getInputProps('sameAsOrganization', { type: 'checkbox' })}
          onChange={handleSameAsChange}
        />
        <AddressFields
          form={form}
          path="address"
          legend="Billing address"
          disabled={sameAsOrganization}
        />
      </Stack>

      <Textarea
        label="Invoice notes"
